#!/usr/bin/env python3
"""Render three static language versions and a deployment-only dist (stdlib)."""
from pathlib import Path
import html,json,hashlib,base64,re,shutil
ROOT=Path(__file__).resolve().parents[1]
BASE='https://www.leosoffice.com/'
LOCALES={'en':('', 'en_US'),'zh-Hant':('zh-hant/','zh_TW'),'zh-Hans':('zh-hans/','zh_CN')}
E=html.escape
icon='''<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M8 7v26h24" stroke="currentColor" stroke-width="2"/><circle cx="27" cy="14" r="5" fill="#ff9b71"/><ellipse cx="27" cy="14" rx="10" ry="3" transform="rotate(-35 27 14)" stroke="#ff9b71"/></svg>'''
# Version the room module and its parent entry point together.
main_path=ROOT/'assets/main.js'
scene_version=hashlib.sha256((ROOT/'assets/scene.js').read_bytes()).hexdigest()[:12]
main_path.write_text(re.sub(r"scene\.js\?v=[a-zA-Z0-9-]+",'scene.js?v='+scene_version,main_path.read_text()))
all_hashes=[]
for lang,(prefix,oglocale) in LOCALES.items():
 d=json.loads((ROOT/'content'/f'{lang}.json').read_text());up='../' if prefix else './'; asset=up+'assets/'
 schema={'@context':'https://schema.org','@type':'ProfilePage','url':BASE+prefix,'name':d['title'],'description':d['description'],'inLanguage':lang,'mainEntity':{'@type':'Person','name':'Leo Knox','url':BASE,'image':BASE+'assets/leo-avatar.jpg','email':'leo@leosoffice.com'}}
 ld=json.dumps(schema,ensure_ascii=False,separators=(',',':'));all_hashes.append("'sha256-"+base64.b64encode(hashlib.sha256(ld.encode()).digest()).decode()+"'")
 alternates=''.join(f'<link rel="alternate" hreflang="{l}" href="{BASE+p}">' for l,(p,_) in LOCALES.items())+f'<link rel="alternate" hreflang="x-default" href="{BASE}">'
 languages=''.join(f'<a data-language="{l}" lang="{l}" hreflang="{l}" href="{up+p}"'+(' aria-current="page"' if l==lang else '')+'>'+{'en':'EN','zh-Hant':'繁','zh-Hans':'简'}[l]+'</a>' for l,(p,_) in LOCALES.items())
 mainhash=hashlib.sha256((ROOT/'assets/main.js').read_bytes()).hexdigest()[:10];stylehash=hashlib.sha256((ROOT/'assets/style.css').read_bytes()).hexdigest()[:10]
 head=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f1e8"><title>{E(d['title'])}</title><meta name="description" content="{E(d['description'],quote=True)}"><link rel="canonical" href="{BASE+prefix}">{alternates}<meta property="og:type" content="website"><meta property="og:site_name" content="Leo’s Office"><meta property="og:title" content="{E(d['title'],quote=True)}"><meta property="og:description" content="{E(d['description'],quote=True)}"><meta property="og:url" content="{BASE+prefix}"><meta property="og:locale" content="{oglocale}"><meta property="og:image" content="{BASE}assets/og-{lang}.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{E(d['title'],quote=True)}"><meta name="twitter:description" content="{E(d['description'],quote=True)}"><meta name="twitter:image" content="{BASE}assets/og-{lang}.png"><link rel="icon" href="{asset}favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{asset}style.css?v={stylehash}"><script type="application/ld+json">{ld}</script><script type="module" src="{asset}main.js?v={mainhash}"></script></head>'''
 nav=''.join(f'<a href="#{target}">{E(text)}</a>' for target,text in zip(['spaces','story','contact'],d['nav']))
 bookmarks=''.join(f'<a href="{url}">{E(label)} ↗</a>' for url,label in zip(['https://image.nimama.de/','https://wp.leoknox.de/','https://key.leoknox.de/'],d['bookmarkNames']))
 tabs=''.join(f'<button data-office-key="{key}" aria-pressed="{str(i==0).lower()}" data-name="{E(d["cards"][i][0],quote=True)}" data-description="{E(d["cards"][i][1],quote=True)}" data-domain="{domain}"><span aria-hidden="true">{symbol}</span>{d["tabs"][i]}</button>' for i,(key,domain,symbol) in enumerate(zip(['dev','me','aploa','agent'],['leoknox.dev','leoknox.me','aploa.com','agent.leoknox.us'],['▱','▥','⌁','▤'])))
 site_links=''.join(f'<a href="https://{domain}/">{domain} ↗</a>' for domain in ['leoknox.dev','leoknox.me','aploa.com','agent.leoknox.us'])
 story=''.join(f'<p data-chapter="{E(d["chapters"][i],quote=True)}">{E(text)}</p>' for i,text in enumerate(d['story']))
 body=f'''<body><a class="skip" href="#main">{d['skip']}</a><div class="wrap"><header class="site-header"><a class="wordmark" href="./" aria-label="Leo’s Office">{icon}<span>Leo’s <i>Office.</i></span></a><div class="header-right"><nav class="nav" id="nav" aria-label="{d['menu']}">{nav}</nav><div class="languages" aria-label="{d['language']}">{languages}</div><button class="menu-button" aria-expanded="false" aria-controls="nav" aria-label="{d['menu']}">☰</button></div></header></div><div class="language-notice" hidden><a id="language-suggestion" href="./"></a><button data-dismiss-language aria-label="{d['dismiss']}">×</button></div><main id="main" class="wrap"><section class="hero" aria-labelledby="hero-title"><div class="hero-heading"><p class="hello">{d['hello']}</p><h1 id="hero-title">{d['heroTitle']}</h1><p class="hero-intro">{d['heroSubtitle']}</p></div><div class="room-wrap"><div class="room" data-fallback="{d['fallback']}" role="img" aria-label="{d['sceneDesc']}"><img class="room-fallback" src="{asset}office-fallback.svg" alt="" width="1000" height="650"><span class="sr-only">{d['sceneDesc']}</span></div><p class="room-note">{d['roomNote']}</p><div class="avatar-sticker"><img src="{asset}leo-avatar.jpg" alt="{d['avatarAlt']}" width="79" height="79"><small>Leo was here.</small></div><span class="room-tag" aria-hidden="true">{d['sceneLabel']}</span><div class="room-controls"><button data-turn="-1" aria-label="{d['turnLeft']}">↶</button><button data-turn="1" aria-label="{d['turnRight']}">↷</button><button class="reset" data-reset>{d['reset']}</button><button class="motion" data-motion data-pause="{d['pause']}" data-resume="{d['resume']}" data-reduced="{d['reduced']}" aria-label="{d['pause']}" aria-pressed="true">Ⅱ</button></div><a class="room-selection" id="room-link" href="https://leoknox.dev/" hidden><span id="room-selection-title"></span> ↗</a><p class="room-caption">{d['roomHint']}</p></div></section><section class="spaces" id="spaces" aria-label="{d['roomSection']}"><div class="space-tabs" role="group" aria-label="{d['roomSection']}">{tabs}</div><div class="space-detail" aria-live="polite"><div><p class="detail-label">ON THE DESK / <span id="detail-domain">leoknox.dev</span></p><h2 id="detail-title">{d['cards'][0][0]}</h2></div><p id="detail-description">{d['cards'][0][1]}</p><a class="visit-link" id="detail-link" href="https://leoknox.dev/">{d['visit']} <span aria-hidden="true">↗</span></a></div><div class="all-sites">{site_links}</div><details class="bookmarks"><summary>{d['bookmarks']}</summary><div class="bookmark-links">{bookmarks}</div></details></section><section class="story" id="story" aria-labelledby="story-title"><div class="story-intro"><div><p class="section-label">{d['storyLabel']}</p><h2 id="story-title">{d['storyHeading']}</h2></div><aside class="sticky-note"><p>{d['sticky']}</p><div class="signature">— Leo</div></aside></div><div class="story-text">{story}</div></section><div class="quote-strip"><span class="little-star" aria-hidden="true">✳</span><span>{d['intro'].replace('<br>',' ')}<br>{d['note'].replace('<br>',' ')}</span><span class="little-star" aria-hidden="true">✳</span></div><section class="contact" id="contact" aria-labelledby="contact-title"><div><p class="section-label">{d['contactLabel']}</p><h2 id="contact-title">{d['contactHeading']}</h2><p>{d['contactNote']}</p></div><div><a class="email" href="mailto:leo@leosoffice.com">leo@leosoffice.com <span aria-hidden="true">↗</span></a><div class="contact-links"><div><a href="https://t.me/realLeoKnox">Telegram ↗</a> &nbsp; / &nbsp; <a href="https://www.nodeseek.com/notification#/message?mode=talk&amp;to=26676">NodeSeek ↗</a></div><button class="copy-email" data-copy data-success="{d['copySuccess']}" data-failure="{d['copyFailure']}">{d['copy']}</button></div><div class="copy-status" role="status" aria-live="polite"></div></div></section></main><footer class="wrap"><div class="site-footer"><p class="footer-note">© 2026 LEO KNOX<br>{d['footer']}</p><div class="footer-right"><time class="local-time" data-time>UTC+8</time><a href="#main">{d['back']}</a></div></div></footer></body></html>'''

 dest=ROOT/prefix/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(head+body)
 if lang=='en':
  error=re.sub(r'<link rel="alternate"[^>]+>','',head).replace(f'<link rel="canonical" href="{BASE}">','<meta name="robots" content="noindex">').replace('<title>'+E(d['title'])+'</title>','<title>404 — Leo’s Office</title>')
  error=error.replace(f'<script type="application/ld+json">{ld}</script>','')
  (ROOT/'404.html').write_text(error+f'<body><main class="wrap error-page"><a class="wordmark" href="./">{icon}Leo’s Office.</a><h1>404</h1><h2>{d["errorHeading"]}</h2><p>{d["errorText"]}</p><a class="back-link" href="./">{d["errorBack"]} ↗</a><p><a href="mailto:leo@leosoffice.com">leo@leosoffice.com</a></p></main></body></html>')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n')
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p+'</loc></url>' for p,_ in LOCALES.values())+'</urlset>\n')
(ROOT/'_redirects').write_text('/cn /zh-hans/ 301\n/cn/ /zh-hans/ 301\n/en / 301\n/en/ / 301\n/index.html / 301\n/zh-hant/index.html /zh-hant/ 301\n/zh-hans/index.html /zh-hans/ 301\n')
(ROOT/'_headers').write_text('''/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  Permissions-Policy: camera=(), microphone=(), geolocation=()
  Content-Security-Policy: default-src 'self'; script-src 'self' '''+' '.join(all_hashes)+'''; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'none';
/assets/*
  Cache-Control: public, max-age=3600
''')
dist=ROOT/'dist';shutil.rmtree(dist,ignore_errors=True);dist.mkdir()
for name in ['index.html','404.html','zh-hant','zh-hans','assets','robots.txt','sitemap.xml','_headers','_redirects']:
 src=ROOT/name;dst=dist/name
 if src.is_dir():shutil.copytree(src,dst)
 else:shutil.copy2(src,dst)
print('Built 3 static language pages, English 404, SEO, hosting rules and dist/.')
